// Frozen legacy contract - legacy clients compile against this
typedef struct LegacyPricing {
    virtual ~LegacyPricing() = default;
    virtual double price(const std::string& sku) const = 0;   // old signature, old style
} LegacyPricing;                                              // [[deprecated]]
class PricingWindow final : public LegacyPricing {            // window over the new core
public:
    explicit PricingWindow(NewCore& core) : core_(core) {}
    double price(const std::string& sku) const override {
        return legacy_quote(core_.quote(sku));                // one mapping TU
    }
private:
    NewCore& core_;
};

