// abi_shim.cpp - the only translation unit the legacy binary links against
extern "C" {
struct lw_ctx;                                   // C++ type stays hidden
lw_ctx* lw_open(const char* dsn);
int     lw_price(lw_ctx* c, const char* sku, double* out) {
    try { *out = legacy_quote(c->core.quote(sku)); return 0; }
    catch (...) { return LW_EINTERNAL; }         // no exception crosses the boundary
}
void lw_close(lw_ctx* c);
